sources = json.loads(Path("source.json").read_text())
answer = []
for source in sources:
    number = source["number"]
    record = {key: source[key] for key in ("code_id", "source_id", "source_sha256", "number")}
    record["proposed_xml"] = Path(f"draft_{number}.xml").read_text().strip()
    record.update(metadata[number])
    record["status"] = "rewrite_draft"
    if "removed_provisions" in record:
        record["change_type"] = "normative_reduction"
        record["reform_policy_id"] = POLICY
    answer.append(record)

Path("answer.json").write_text(json.dumps(answer, ensure_ascii=False, indent=2) + "\n")
print(f"answer.json : {len(answer)} articles")
